#!/usr/bin/env python3
"""Read-only aggregation; never invokes a solver or changes historical evidence."""
from common import *
import csv,collections
BASE=ROOT/'results/round3_semantics'
def rows(p):return [json.loads(l) for l in p.open()] if p.exists() else []
def main():
 old=list(csv.DictReader((BASE/'offline/reclassified_targets.csv').open()));actions=[]
 for job in read(ROOT/'manifests/round2_a_plan.json')['runs']:
  actions.extend(rows(ROOT/job['output']/'a_actions.jsonl'))
 sessions=[]
 for job in read(ROOT/'manifests/round3_d1_plan.json')['jobs']:
  d=ROOT/job['output'];s=read(d/'summary.json');cost=rows(d/'cost_ledger.jsonl')[-1];back=[b for b in rows(d/'a_backend_calls.jsonl') if 'funnel' in b];funnel=collections.Counter()
  for b in back:funnel.update(b['funnel'])
  ex=read(d/'exact.json');semantic=rows(d/'semantic.jsonl');sessions.append({'id':job['id'],**s,'official_covered':ex['covered'],'official_total':ex['total'],'formal_legal':ex['legal'],'process_seconds':read(d/'terminal.json')['process_seconds'],'backend_calls':len(back),'metadata_received':sum(b['metadata_received'] for b in back),'funnel':dict(funnel),'cost_categories_cumulative':cost['categories'],'A_metadata_registration_seconds':sum(cost['categories'].get(k,0) for k in ['binding_seconds','request_register_seconds','route_metadata_seconds']),'semantic_overflows':sum(bool(r.get('overflow')) for r in semantic),'raw_model_layers':dict(collections.Counter(r['layer'] for r in semantic if r['kind']=='model_layer'))})
 oracle=read(BASE/'oracle/summary.json');qs={q:dict(collections.Counter(r['result'] for r in oracle['results'] if r['query']==q)) for q in ['Q1','Q2','Q3','Q4','Q5','Q6']}
 chain=list(csv.DictReader((BASE/'analysis/event_chain.csv').open()));app=[r for r in chain if r['run_id']=='convert_apply_trace' and r['kind']=='suggestion'];micro=list(csv.DictReader((BASE/'analysis/cause_matrix.csv').open()));groups=[]
 for cp in read(ROOT/'manifests/round3_d3_plan.json')['cases']:
  rs=[r for r in micro if r['checkpoint_id']==cp['case_id']];groups.append({'checkpoint_id':cp['case_id'],'historical_query':cp['query_id'],'historical_decision':cp['decision_id'],'cells':{r['cell']:{k:r.get(k,'') for k in ['result','checkpoint_status','process_seconds','final_internal_assignment','M_leaf','actual_atom_truth','value_hits','observation_hits','final_token_direct_transmission','initial_token_withdrawn','comparison_limit']} for r in rs}})
 facts={'historical':{'actions':len(actions),'overrides':sum(a['phase_changed'] for a in actions),'unique_legacy_keys':len({a['canonical_key'] for a in actions}),'actual_unique_atoms':'unknown; historical raw AST missing','target_records':len(old),'unique_targets':len({(r['node'],r['bit'],r['desired']) for r in old}),'queries_with_actions':len({(r['run_id'],r['query_id']) for r in old}),'records_unreached':sum(r['metric_reached']=='False' for r in old)},'D1_sessions':sessions,'D1_chain':read(BASE/'analysis/chain_summary.json'),'apply_initial_tokens_withdrawn':sum(r['original_token_withdrawn']=='True' for r in app),'apply_overflow_events':sum(r['overflow']=='True' for r in app),'apply_internal_to_leaf_without_direct':sum(r['first_broken_link']=='internal_assignment_to_M_leaf' and r['final_token_direct_transmission']=='False' for r in app),'D2_queries':qs,'D2_total_check_seconds':sum(r['seconds'] for r in oracle['results']),'D2_max_check_seconds':max(r['seconds'] for r in oracle['results']),'D3':read(BASE/'micro/audit_summary.json'),'D3_groups':groups,'D3_total_parent_seconds':sum(float(r['process_seconds']) for r in micro),'mapping':read(BASE/'mapping/summary.json')}
 write(BASE/'analysis/report_facts.json',facts)
 strategy={'one_factor_only':'preprocessing semantic correspondence for existing native Bool decisions','evidence':['All 512 in-window decisions per main instance in observe were unmapped','Two of the 16 frozen representatives have independently proved original correspondence','No D1 or D3 target observation hit; local activation did not preserve the requested phase in returned real models'],'proposed_next_scope':'Restore only independently verified original-expression correspondence through actual converter definitions, then query the current single-sided gap. Keep the native decision variable, phase arbitration, relevance policy, fixed-variable policy, window, quota, CCSS and seed unchanged.','acceptance':'Require a real-instance verified target -> native action -> theory -> actual model -> official observation chain, or explicitly classify channel inapplicable.','limitations':['Two proven gates arose at coverage version zero and do not themselves prove an available demand','No full-state causal D3 clone','Historical actual mapping remains unknown; Q5/Q6 are vacuous'],'implemented_this_round':False,'performance_claim':'No evidence of superiority to complete HighDiv; no new performance matrix authorized'}
 write(BASE/'analysis/strategy_decision.json',strategy);print(json.dumps({k:v for k,v in facts.items() if k not in ['D1_sessions','D1_chain','D3_groups']},ensure_ascii=False))
if __name__=='__main__':main()
